'use strict';

// Copies the client build into the folder Vercel serves from its CDN.
// Files that Express must render or generate are left out, because a static file
// on Vercel always wins over the function:
//   index.html  -> SSR template (otherwise "/" would be served without rendering)
//   robots.txt, sitemap.xml -> generated by discoveryRoutes / sitemapRoutes
//   .vite/      -> build manifest, read by the server only
// Run after `npm run build`: node scripts/vercel-static.cjs
const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const source = path.join(root, 'client', 'dist', 'client');
const target = path.join(root, 'dist-vercel');
const excluded = new Set(['index.html', 'robots.txt', 'sitemap.xml', '.vite']);

if (!fs.existsSync(path.join(source, 'index.html'))) {
  console.error(`Client build not found in ${source}. Run "npm run build" first.`);
  process.exit(1);
}

fs.rmSync(target, { recursive: true, force: true });
fs.cpSync(source, target, {
  recursive: true,
  filter: (file) => !excluded.has(path.relative(source, file).split(path.sep)[0]),
});

console.log(`Static files copied to ${path.relative(root, target)}`);
